"""Build explicitly synthetic context pairs and a separate human-review worksheet."""
import csv,hashlib,json
from collections import Counter
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'Datasets/CustomForum'
# Independently authored scenarios, not mined from existing test errors or generated by paraphrasing test posts.
PAIRS=[
 ('submission_button','The assignment is due tonight, but the submit button does nothing. I have tried two browsers. Could staff help me submit before the deadline?','The submit button works now and my assignment has a receipt. Thank you; no further help is needed.'),
 ('exam_login','My exam starts in twenty minutes and my course account is locked. Password reset has not worked. I need staff to restore access.','My account has been unlocked and I have entered the exam successfully. The earlier login problem is resolved.'),
 ('quiz_timer','The graded quiz gave me two minutes instead of the published thirty. It closed before I could answer. Can the teaching team correct this attempt?','The teaching team corrected the timer and reopened my attempt. I have completed the quiz, so this issue is resolved.'),
 ('enrollment_block','I meet the prerequisite, but the registration system says I do not and blocks enrollment. Registration closes today. Could someone check my record?','The prerequisite record has been corrected and my enrollment is confirmed. I no longer need assistance with registration.'),
 ('missing_grade','My completed final project has no grade in the portal, and the grade appeal window closes tomorrow. Could the instructor investigate?','The missing final project grade has appeared and is correct. I am posting to confirm that the issue has been resolved.'),
 ('receipt_missing','The upload ended with an error and I have no submission receipt. The deadline is in an hour. Could staff confirm whether my file was received?','I found the submission receipt and checked that the correct file was received on time. There is nothing left for staff to check.'),
 ('autograder_down','Every submission to the required autograder returns a server error. The deadline is approaching and I cannot complete the assessment. Could staff investigate?','The autograder is available again and my submission has been accepted. Thanks for fixing the server problem.'),
 ('required_pdf','The only copy of the instructions for tonight\'s assessment is an unreadable PDF. Could the teaching team provide a readable version?','A readable copy of the assessment instructions is now available and I downloaded it successfully. This problem is resolved.'),
 ('video_access','The required lecture for tomorrow\'s graded task is unavailable to my account. Other resources work. Could staff restore access?','I can open the required lecture now and have finished watching it. I no longer need help with access.'),
 ('accommodation','My approved extra time is not applied to tomorrow\'s exam. The accessibility approval is already on file. Could the teaching team correct the exam settings?','The approved extra time now appears correctly in my exam settings. Thank you for resolving this before the exam.'),
 ('conflicting_exam_date','The exam timetable and course announcement give different dates for the final exam. One date is tomorrow. Could the instructor confirm which is correct?','The instructor has confirmed the exam date and updated the conflicting announcement. I understand the schedule now.'),
 ('exam_room','My exam admission slip lists a room that the campus notice says is closed. The exam is this afternoon. Could staff confirm where I should go?','The corrected exam room has been announced and my admission slip is updated. The location issue is resolved.'),
 ('public_submission','My assessment submission appears publicly visible to other students even though it should be private. Could staff check the sharing settings promptly?','Staff corrected the sharing settings and confirmed that my assessment submission is private. No further action is needed.'),
 ('account_compromise','Someone changed the email address on my course account and I cannot regain access. I have contacted support, but an assessment is due today. Could the teaching team help with course access?','Support restored my account and the teaching team confirmed my assessment access. I am no longer asking for intervention.'),
 ('group_upload','Our group assignment portal rejects the designated submitter and nobody else can upload. The project is due tonight. Could staff enable submission?','Our designated submitter can upload now and the group project has a valid receipt. Thank you; the group is no longer blocked.'),
 ('lab_booking','The booking system will not let me reserve the compulsory assessed lab despite available places. The booking deadline is today. Could staff check the restriction?','My compulsory lab booking is confirmed and appears on my timetable. The restriction has been fixed.'),
 ('late_penalty','The system marked my submission late even though the receipt shows it before the published deadline. The appeal closes tomorrow. Could the teaching team review the penalty?','The teaching team checked the receipt and removed the incorrect late penalty. I am satisfied with the correction.'),
 ('payment_access','My course payment was processed twice and my learning account is now suspended. I cannot access today\'s assessment. Could staff help restore course access?','The duplicate payment has been resolved and my learning account is active again. I can access the assessment.'),
 ('timezone_deadline','The task page and submission portal show different time zones for a deadline later today. Could staff confirm the actual closing time before the portal locks?','The deadline time zone has been clarified and I have submitted successfully. I do not need another response.'),
 ('oral_exam_link','My scheduled oral exam begins shortly, but the meeting link in my appointment is missing. Could the examiner send the correct joining information?','The examiner sent the working meeting link and I joined my oral exam. The missing-link problem has been resolved.'),
 ('wrong_dataset','The mandatory assessment dataset has different columns from the published specification, so the starter program cannot run. Could staff check the release before the deadline?','A corrected assessment dataset has been released and the starter program runs as expected. Thank you for the replacement.'),
 ('screen_reader','The required quiz image has no accessible text and I use a screen reader. The quiz closes tonight. Could staff provide the approved accessible version?','The accessible version of the quiz is now available and I completed it. I no longer need assistance with that item.'),
 ('incorrect_formula','The formula in the graded task conflicts with the correction announced in class. Answers are due today. Could the instructor clarify which version will be marked?','The instructor confirmed the corrected formula and updated the graded task. The inconsistency is resolved.'),
 ('peer_review_locked','My assigned peer-review submission is inaccessible, and the review deadline is tonight. Could staff reassign it or restore access?','Staff reassigned the inaccessible submission and I finished the peer review before the deadline. No further help is needed.'),
 ('extension_request','I submitted the required documentation for an extension, but my portal will close in three hours and I have no decision. Could staff check the request?','My extension has been approved and the new deadline appears in the portal. I am posting only to confirm the update.'),
 ('attendance_record','My compulsory lab attendance is missing from the record and this prevents final assessment eligibility. The correction deadline is today. Could staff review it?','The lab attendance record has been corrected and my assessment eligibility is confirmed. This issue is resolved.'),
 ('registration_error','The exam registration portal puts me in the wrong course and will not allow a correction. Registration closes tonight. Could the administration or teaching team help?','My exam registration now shows the correct course. I have checked the confirmation and no longer need help.'),
 ('exam_webcam','The exam software rejects my approved camera during the required equipment check, and the exam is tomorrow. Could staff advise on the approved alternative?','The approved alternative passed the equipment check and my exam setup is confirmed. The earlier camera problem is resolved.'),
 ('outage_alternative','A local network outage prevents me uploading the assessment before the imminent deadline. Could staff confirm an approved alternative submission method?','Staff accepted my assessment through the approved alternative channel and sent a receipt. I am not requesting another exception.'),
 ('wrong_file_locked','I accidentally submitted the wrong file and the portal is locked before the stated closing time. Could staff reopen it so I can submit the correct work?','Staff reopened the portal and I replaced the wrong file with the correct submission. The replacement receipt is valid.'),
 ('course_removed','The system removed me from the course even though my enrollment is confirmed. I cannot access an assessment due today. Could staff check my access?','My course enrollment and assessment access have both been restored. Thank you for resolving the system error.'),
 ('required_reading','The required reading for the graded task is behind a broken course-library link. The task closes tomorrow. Could staff provide the working licensed access route?','The course-library link has been repaired and I can access the required reading. This access problem is resolved.'),
 ('starter_version','The provided starter files require a package version that is unavailable in the mandatory lab environment. Could staff correct the environment before tomorrow\'s practical exam?','The lab environment has been updated and the starter files now run correctly. The version mismatch is resolved.'),
 ('answer_field','The graded quiz answer field rejects all decimal numbers even though the question requires a decimal. Could the teaching team check it before the quiz closes?','The answer field now accepts the required decimal format and my attempt is recorded. Thank you for fixing it.'),
 ('announcements_hidden','My course announcement page is blank and I cannot see the exam joining instructions for this evening. Could staff restore access or provide the instructions?','The announcement page is visible again and I have the exam joining instructions. I no longer need help with that page.'),
 ('lab_database','The shared database required for the assessed lab is offline. Our submission window ends today. Could the teaching team investigate the service?','The shared database has been restored and my assessed lab submission is complete. The service issue is resolved.'),
 ('timetable_clash','Two compulsory graded assessments are scheduled at the same time for my registered modules. The timetable becomes final tomorrow. Could staff arrange a resolution?','The assessment timetable clash has been resolved and I have the confirmed alternative slot. Thank you for arranging it.'),
 ('withdrawal_error','My record says I withdrew from the course, but I did not request withdrawal. It blocks an assessment registration that closes today. Could staff investigate?','The mistaken withdrawal has been reversed and I registered for the assessment. My course record is now correct.'),
 ('reset_email','I cannot sign in to take a quiz due tonight because the password-reset email never arrives. I checked spam and the account address. Could support or staff help?','The password-reset email arrived, I signed in, and I completed the quiz. I am confirming that I no longer need help.'),
 ('grading_rubric','The project rubric in the submission portal differs from the rubric used for our required presentation tomorrow. Could the instructor clarify the assessment criteria?','The instructor confirmed the applicable rubric and corrected the portal copy. I understand the criteria now.'),
]
AMBIGUOUS=[
 'I need help.', 'It does not work.', 'Can someone explain this?', 'What should I do now?',
 'This is urgent.', 'I cannot find it.', 'Any update?', 'I am confused about the last part.',
 'Could you look at my question?', 'The answer seems wrong.', 'I have a problem with the course.', 'Please reply.',
]
OUTSIDE=[
 'What is the weather in Tokyo today?', 'Recommend a restaurant for dinner.', 'Write a poem about the ocean.',
 'Translate this shopping list into French.', 'Who won the football match last night?', 'Tell me a joke.',
 'I want to sell my old bicycle.', 'The train to the airport leaves at six.', 'My favourite film is a comedy.',
 'Please generate a logo for my company.', 'The garden needs watering.', 'What is the capital of Canada?',
]
NEUTRAL=[
 'Thank you for the clear explanation. I understand the lesson now.',
 'I finished the optional practice exercises and enjoyed them.',
 'Here is a study summary I wrote for classmates. I am not requesting a staff response.',
 'The deadline is tonight, and I have already submitted successfully. This is only a progress update.',
 'A classmate wrote “I cannot submit” earlier. They have since confirmed that their upload succeeded.',
 'I was worried about the exam, but I found the official instructions and my question is answered.',
 'I am introducing myself to the class and looking forward to the course.',
 'I solved my installation problem by following the course guide. Sharing that the guide worked.',
 'This example sentence contains the words “urgent” and “deadline” for a language exercise; it is not a request for help.',
 'Our study group meets on Saturday to discuss optional readings.',
 'I agree with the previous discussion of the historical example.',
 'The video is working for me now. Thanks to the support team.',
 'I received my certificate and checked that my details are correct.',
 'I reviewed my marked work and understand the feedback.',
 'I no longer need an extension because I completed and submitted the assignment.',
 'The phrase “Please help immediately” is quoted in my analysis of forum language, not addressed to the teaching team.',
]

def split(group):
    bucket=int(hashlib.sha256(('custom-v1:'+group).encode()).hexdigest()[:8],16)%10
    return 'train' if bucket<6 else ('validation' if bucket<8 else 'challenge')

def main():
    OUT.mkdir(parents=True,exist_ok=True);rows=[]
    def add(group,case,text,draft,action,notes):
        rows.append({'post_id':f'custom_{len(rows)+1:04d}','scenario_group':group,'split':split(group),
            'case_type':case,'text':text,'draft_priority':'' if draft is None else draft,'draft_action':action,
            'provenance':'assistant_authored_synthetic','label_origin':'assistant_draft',
            'review_status':'pending','notes':notes})
    for group,blocked,resolved in PAIRS:
        add(group,'blocked',blocked,1,'PRIORITY','Draft: unresolved course blocker or staff action needed promptly.')
        add(group,'resolved',blocked+' Update: '+resolved,0,'NORMAL','Same reported problem, now explicitly resolved. Read the complete post.')
    for i,text in enumerate(AMBIGUOUS):add(f'ambiguous_{i}','missing_context',text,None,'REVIEW','Insufficient context for a defensible binary label.')
    for i,text in enumerate(OUTSIDE):add(f'outside_{i}','outside_scope',text,None,'OUT_OF_SCOPE','Not an English student course-support post.')
    for i,text in enumerate(NEUTRAL):add(f'neutral_{i}','neutral_or_quoted',text,0,'NORMAL','Draft: informational, resolved, or quoted urgency with no current help request.')
    # Append only: the original 120 IDs stay stable for existing review worksheets.
    # Positive updates stop the marker "Update" becoming a shortcut for the NORMAL label.
    for group,blocked,_ in PAIRS:
        add(group,'still_blocked_update',blocked+' Update: I retried the suggested steps, but the problem is still preventing me from completing the course task. I still need assistance from the teaching team.',
            1,'PRIORITY','Draft counterexample: an update does not imply resolution. Same scenario group as the resolved variant.')
    assert len(rows)==160 and len({r['text'] for r in rows})==160
    source_hashes=set()
    for name in ['UPenn','Stanford']:
        with (ROOT/f'Datasets/{name}/processed.csv').open() as f:
            source_hashes.update(hashlib.sha256(' '.join(r['text_clean'].casefold().split()).encode()).hexdigest() for r in csv.DictReader(f))
    assert not any(hashlib.sha256(' '.join(r['text'].casefold().split()).encode()).hexdigest() in source_hashes for r in rows)
    with (OUT/'draft_examples.csv').open('w',encoding='utf-8-sig',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=list(rows[0]));writer.writeheader();writer.writerows(rows)
    review=OUT/'reviewed_labels.csv'
    if not review.exists():
        with review.open('w',encoding='utf-8-sig',newline='') as f:
            fields=['post_id','reviewer','adjudicated_priority','adjudicated_action','review_status','reviewer_notes']
            writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader()
            writer.writerows({'post_id':r['post_id'],'review_status':'pending'} for r in rows)
    else:
        with review.open(encoding='utf-8-sig',newline='') as f:
            existing=list(csv.DictReader(f))
        missing=[r for r in rows if r['post_id'] not in {e['post_id'] for e in existing}]
        if missing:
            with review.open('a',encoding='utf-8',newline='') as f:
                writer=csv.DictWriter(f,fieldnames=['post_id','reviewer','adjudicated_priority','adjudicated_action','review_status','reviewer_notes'])
                writer.writerows({'post_id':r['post_id'],'review_status':'pending'} for r in missing)
    with review.open(encoding='utf-8-sig',newline='') as f:reviews=list(csv.DictReader(f))
    approved_count=sum(r['review_status']=='approved' for r in reviews)
    metadata={'version':'custom-v2','rows':len(rows),'scenario_groups':len({r['scenario_group'] for r in rows}),
              'provenance':'assistant-authored synthetic examples, not collected student records',
              'label_status':'draft with separate human-review worksheet','human_approved_rows':approved_count,
              'case_types':dict(Counter(r['case_type'] for r in rows)),'splits':dict(Counter(r['split'] for r in rows)),
              'exact_overlap_with_real_sources':0,'training_default':'exclude all unreviewed examples',
              'split_policy':'deterministic scenario-group split; blocked/resolved pair cannot cross splits',
              'development_history':'40 still-blocked updates added after observing poor resolution handling; not an independent benchmark',
              'draft_sha256':hashlib.sha256((OUT/'draft_examples.csv').read_bytes()).hexdigest()}
    (OUT/'metadata.json').write_text(json.dumps(metadata,indent=2)+'\n')
    (OUT/'ANNOTATION_GUIDE.md').write_text('# CustomForum annotation guide\n\n'
        'These are synthetic drafts. They are not an independently labelled real-world benchmark.\n\n'
        'Read the whole text, including any final update. Judge the current need for prompt teaching-team support.\n'
        '- PRIORITY / 1: a current, unresolved course issue needs a timely staff response.\n'
        '- NORMAL / 0: informational, resolved, or no current actionable request.\n'
        '- REVIEW / blank: context is insufficient or the correct label is debatable.\n'
        '- OUT_OF_SCOPE / blank: the text is not a supported student forum post.\n\n'
        'The original source benchmark still uses urgency > 4. Its labels are not overwritten.\n'
        'Enter reviewer name, adjudicated action, and (for PRIORITY/NORMAL only) adjudicated_priority in reviewed_labels.csv.\n'
        'Set review_status to approved only after review. For disputed cases, obtain a second independent judgement and record the resolution.\n'
        'The draft file can be regenerated. The review worksheet is never overwritten by the generator.\n'
        'Only approved train rows may enter a training ablation. Validation/challenge scenarios remain held out, including every variant of a scenario.\n'
        'Performance on approved synthetic scenarios is reported separately from real UPenn/Stanford test performance.\n')
    print(json.dumps(metadata,indent=2))

if __name__=='__main__':main()
